function parseRelaxed(candidate) {
  try {
    return JSON.parse(candidate);
  } catch (error) {
    // fall through to trailing-comma tolerance
  }
  try {
    return JSON.parse(candidate.replace(/,\s*([}\]])/g, "$1"));
  } catch (error) {
    return undefined;
  }
}

